function showManualRoom(){openModal(`<h2>Créer une pièce cotée</h2><p>Saisissez ses dimensions intérieures réelles. Vous pourrez ensuite déplacer les angles pour former un L, un U ou un contour libre.</p><form id="manual-room-form" class="fields"><label>Nom de la pièce<input id="manual-name" value="Salle de bains" maxlength="100" required></label><div class="cols"><label>Longueur<input id="manual-width" type="number" min=".01" step="any" placeholder="Dimension réelle" required></label><label>Profondeur<input id="manual-depth" type="number" min=".01" step="any" placeholder="Dimension réelle" required></label></div><div class="cols"><label>Unité<select id="manual-unit"><option value="100">mètres</option><option value="1">centimètres</option></select></label><label>Hauteur (cm)<input id="manual-height" type="number" min="180" max="400" value="260" required></label></div><p class="subtle">Hauteur initiale : 260 cm, à contrôler. L’emplacement proposé sur le plan reste à positionner et à valider.</p><p id="modal-status" class="modal-status" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Annuler</button><button class="primary" type="submit">Créer la pièce</button></div></form>`,()=>{$('#manual-room-form').onsubmit=e=>{e.preventDefault();try{if(project.rooms.length>=60)throw Error('60 pièces maximum.');if(project.source&&!project.scale)throw Error('Définissez d’abord l’échelle du fond de plan dans « Mon plan ».');const unit=number('#manual-unit'),w=number('#manual-width')*unit,d=number('#manual-depth')*unit,h=number('#manual-height');if(![w,d,h].every(Number.isFinite)||w<20||d<20||w>50000||d>50000||h<180||h>400)throw Error('Dimensions : de 20 cm à 500 m ; hauteur de 180 à 400 cm.');record();const scale=project.scale||1,all=project.rooms.flatMap(r=>r.points),x=all.length?bounds(all).maxX+50/scale:project.source?view.x+view.w*.3:0,y=all.length?bounds(all).minY:project.source?view.y+view.h*.3:0,r=newRoom([[x,y],[x+w/scale,y],[x+w/scale,y+d/scale],[x,y+d/scale]],$('#manual-name').value.trim().slice(0,100)||'Ma pièce');r.height=h;project.scale=scale;project.rooms.push(r);selected=r.id;step='rooms';mode='select';modal.close();setMode('select');changed();mobile('plan');fit();}catch(error){modalStatus(error.message);}};});}
function showCalibration(){const points=clone(draft);if(distance(...points)<1){draft=[];renderBoard();return notify('Choisissez deux points distincts, assez éloignés.');}openModal(`<h2>Définir l’échelle du plan</h2><p>Quelle est la distance réelle entre les deux points sélectionnés ? Relevez une cote lisible sur le document.</p><form id="scale-form" class="fields"><div class="cols"><label>Distance réelle<input id="real-distance" type="number" min=".001" step="any" required autofocus></label><label>Unité<select id="distance-unit"><option value="100">mètres</option><option value="1">centimètres</option><option value=".1">millimètres</option></select></label></div><p class="note">Cette échelle s’applique à toutes les pièces de ce plan. Leurs dimensions devront être validées à nouveau. Une photo en perspective ne garantit pas un métré exact.</p><p id="modal-status" class="modal-status" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Annuler</button><button type="submit" class="primary">Appliquer l’échelle</button></div></form>`,()=>{$('#scale-form').onsubmit=e=>{e.preventDefault();const cm=number('#real-distance')*number('#distance-unit'),scale=cm/distance(...points);if(!Number.isFinite(scale)||scale<=0||scale>100000)return modalStatus('Saisissez une distance réelle valide.');for(const r of project.rooms){const error=roomError(r,scale);if(error)return modalStatus(r.name+' : '+error);}record();project.scale=scale;modal.close();setMode('select');changed({all:true});notify('Échelle appliquée. Contrôlez les contours et les dimensions avant validation.');};});}
function planPlinthControls(r,q){const settings=plinthSettings(r.plinths),products=matchingPlinths(r);return `<section class="section fields"><h3>Plinthes</h3><label>Choisir les plinthes<select data-plan-plinth-type>${products.length?`<option value="factory" ${settings.type==='factory'?'selected':''}>Plinthes assorties du fabricant</option>`:''}<option value="tile" ${settings.type==='tile'?'selected':''}>Découpées dans le carrelage</option><option value="wood" ${settings.type==='wood'?'selected':''}>Bois blanc · 2,20 m</option></select></label>${settings.type==='factory'?`<label>Référence fabricant<select data-plan-plinth-product>${products.map(p=>`<option value="${esc(p.key)}" ${p.reference===settings.product?.reference?'selected':''}>${esc(p.reference)} · ${p.height} × ${p.length} cm</option>`).join('')}</select></label>`:''}<label class="check"><input data-plan-plinth-aligned type="checkbox" ${settings.aligned?'checked':''}><span>Aligner les joints des plinthes sur les carreaux</span></label><div class="plinth-kpis"><div><span>À poser</span><strong>${fmt(q.plinths?.net)} ml</strong></div><div><span>Avec chutes</span><strong>${fmt(q.plinths?.debit)} ml</strong></div></div><button id="mark-no-plinth">Marquer une partie sans plinthe</button><button id="clear-no-plinth">Rétablir les plinthes sur cette pièce</button><p class="subtle">Glissez sur une partie de mur pour retirer sa plinthe ; touchez pour retirer le mur entier. Les zones retirées apparaissent en pointillés rouges. Portes et baies au sol déduites automatiquement.</p>${Object.keys(r.plinthExclusions||{}).length?'<p class="note">Des parties de murs sont sans plinthe.</p>':''}</section>`;}
