function sendProject(){openModal(`<h2>Envoyer votre projet</h2><p>Ce fichier permet de reprendre le projet en cours sur un autre ordinateur ou smartphone, avec ses pièces, ses choix et la fiche client.</p><p>Le travail est conservé localement sur chaque appareil. Répétez cette opération lorsque vous changez de poste pour emporter la dernière version.</p><div class="fields"><button id="send-project-file" class="primary">Enregistrer le fichier de reprise</button><button id="share-project-file">Partager le fichier</button><button data-close>Fermer</button></div>`,()=>{$('#send-project-file').onclick=()=>download(project,filename()+'-projet.json');$('#share-project-file').onclick=async()=>{const file=new File([JSON.stringify(project)],filename()+'-projet.json',{type:'application/json'});try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:project.title});else download(project,file.name);}catch(e){if(e.name!=='AbortError')notify(e.message);}};});}
function openingSettings(id){const r=room(),o=r?.openings.find(o=>o.id===id);if(!o)return;editingOpening=id;const d=OPENINGS[o.kind]||OPENINGS[o.type]||OPENINGS.door;
 openModal(`<p class="eyebrow">OUVERTURE SUR LE PLAN</p><h2>${esc(d.label)}</h2><p class="subtle">Glissez l’ouverture sur son mur pour la déplacer. Les dimensions sont en centimètres.</p><form id="opening-edit" class="fields">${d.widths?`<label>Format standard<select id="opening-standard">${[...new Set([...d.widths,o.width])].sort((a,b)=>a-b).map(w=>`<option value="${w}" ${w===o.width?'selected':''}>${w} × ${d.height} cm</option>`).join('')}</select></label>`:`<div class="cols"><label>Largeur sur mesure (cm)<input id="opening-width-new" type="number" min="40" max="600" step="1" value="${o.width}"></label><label>Hauteur sur mesure (cm)<input id="opening-height-new" type="number" min="40" max="${r.height}" step="1" value="${o.height}"></label></div>`}<label>Couleur<select id="opening-color-new">${COLORS.map(([v,l])=>`<option value="${v}" ${o.color===v?'selected':''}>${l}</option>`).join('')}</select></label><p>Allège : ${fmt(o.sill,0)} cm · hauteur ${fmt(o.height,0)} cm.</p>${o.type==='window'?'<button type="button" id="opening-front">Régler la hauteur en vue de face</button>':''}<p id="modal-status" class="modal-status" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Fermer</button><button class="primary">Appliquer</button></div></form>`,()=>{$('#opening-edit').onsubmit=e=>{e.preventDefault();const next={...o,width:Number($('#opening-standard')?.value||$('#opening-width-new')?.value||o.width),height:Number($('#opening-height-new')?.value||d.height),color:$('#opening-color-new').value};next.ral=COLORS.find(c=>c[0]===next.color)[1].match(/\d{4}/)[0];const error=roomError({...r,openings:r.openings.map(x=>x.id===id?next:x)},project.scale);if(error)return modalStatus(error);record();Object.assign(o,next);changed({geometry:true});openingSettings(id);};$('#opening-front')?.addEventListener('click',()=>openingElevation(o));});
}
function openingElevation(o){const r=room(),w=distance(r.points[o.wall],r.points[(o.wall+1)%r.points.length])*project.scale;openModal(`<h2>Vue de face · ${esc(OPENINGS[o.kind]?.label||'Fenêtre')}</h2><p>Glissez la fenêtre verticalement. Le déplacement de sa hauteur est réservé à cette vue.</p><svg id="opening-elevation" viewBox="-10 -10 ${w+20} ${r.height+20}" class="opening-elevation"><rect x="0" y="0" width="${w}" height="${r.height}" fill="#eeeae1" stroke="#696b62"/><rect id="elevation-window" x="${o.start}" y="${r.height-o.sill-o.height}" width="${o.width}" height="${o.height}" fill="#c7dce4" stroke="${COLORS.find(c=>c[0]===o.color)?.[2]||'#fff'}" stroke-width="5"/><text id="elevation-label" x="10" y="${r.height-10}">Allège : ${o.sill} cm</text></svg><label>Allège (cm)<input id="elevation-sill" type="number" min="0" max="${r.height-o.height}" value="${o.sill}"></label><div class="dialog-actions"><button id="elevation-back">Retour</button><button class="primary" id="elevation-apply">Appliquer</button></div>`,()=>{let start=null,value=o.sill;const svg=$('#opening-elevation'),draw=()=>{$('#elevation-window').setAttribute('y',r.height-value-o.height);$('#elevation-label').textContent='Allège : '+value+' cm';$('#elevation-sill').value=value;};svg.onpointerdown=e=>{if(e.target.id!=='elevation-window')return;start={y:e.clientY,sill:value};svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!start)return;value=Math.max(0,Math.min(r.height-o.height,Math.round(start.sill-(e.clientY-start.y)/svg.getBoundingClientRect().height*(r.height+20))));draw();};svg.onpointerup=()=>start=null;$('#elevation-sill').oninput=e=>{value=Math.max(0,Math.min(r.height-o.height,Number(e.target.value)));draw();};$('#elevation-apply').onclick=()=>{record();o.sill=value;changed({geometry:true});openingSettings(o.id);};$('#elevation-back').onclick=()=>openingSettings(o.id);});}
function createOpening(point,kind=openingKind){const r=room(),defaults=OPENINGS[kind],pos=wallPosition(r.points,point,project.scale,defaults.width);if(!pos||pos.distance>Math.max(25/project.scale,view.w/20))return notify('Déposez l’ouverture sur un mur assez long.');const o={id:uid(),kind,type:defaults.type,width:defaults.width,height:defaults.height,sill:defaults.sill,color:'white',ral:'9016',wall:pos.wall,start:pos.start},error=roomError({...r,openings:[...r.openings,o]},project.scale);if(error)return notify(error);record();r.openings.push(o);mode='select';changed({geometry:true});openingSettings(o.id);}
function showOpening(id=null){if(typeof id==='string')return openingSettings(id);if(!room()||!project.scale)return notify('Créez d’abord une pièce cotée.');openModal(`<p class="eyebrow">PORTES & FENÊTRES</p><h2>Ajouter une ouverture</h2><p>Maintenez le clic ou le doigt sur un modèle et glissez-le sur un mur. Vous pouvez aussi choisir le modèle, puis toucher le mur.</p><div class="opening-palette">${Object.entries(OPENINGS).map(([kind,d])=>`<button class="opening-choice" data-opening-kind="${kind}"><span class="opening-icon ${kind}" aria-hidden="true"></span><b>${d.label}</b><small>${d.width} × ${d.height} cm</small></button>`).join('')}</div><div class="dialog-actions"><button data-close>Fermer</button></div>`,()=>{$$('[data-opening-kind]').forEach(el=>{el.onpointerdown=e=>{e.preventDefault();openingKind=el.dataset.openingKind;mode='opening';drag={id:e.pointerId,type:'palette',kind:openingKind,point:[e.clientX,e.clientY],moved:false};};el.onclick=()=>{openingKind=el.dataset.openingKind;setMode('opening');};});});}

