async function duplicateProject(){if(!project.rooms.length&&!project.source)return notify('Ajoutez d’abord un plan ou une pièce.');try{await saveLocal(project);project=clone(project);project.id=uid();project.title=(project.title+' · copie').slice(0,120);project.updatedAt=new Date().toISOString();undoStack=[];redoStack=[];changed();await persist(false);notify('Une copie indépendante du projet a été créée.');}catch(e){notify(e.message);}}
function hydrateCatalogue(value){if(!catalogue)return;for(const r of value.rooms){const t=r.tile,match=catalogue.products.find(p=>p.key===t.key)||catalogue.products.find(p=>p.brand===t.brand&&p.collection===t.collection&&p.colorId===t.colorId&&p.format===t.format);if(!match||t.brand==='Libre')continue;r.tile={...newTile(),...clone(match),...t,key:match.key,reference:t.reference||match.reference,preview:t.preview||match.preview,purchaseHT:t.purchaseOverride?t.purchaseHT:match.purchaseHT,purchasePaletteHT:match.purchasePaletteHT,priceSource:t.purchaseOverride?t.priceSource:match.priceSource,packArea:t.packArea??match.packArea,packPieces:t.packPieces??match.packPieces,packSource:t.packSource||match.packSource,packVerified:t.packArea?t.packVerified:match.packVerified};syncPlinthProduct(r);}}
function applyProject(value){project=parseProject(JSON.stringify(value));hydrateCatalogue(project);savedSignature=projectSignature(project);transferRooms.clear();transferInitialized=false;selected=project.rooms[0]?.id||null;undoStack=[];redoStack=[];cache.clear();setMode('select');step='plan';showTiles=false;renderAll();fit();mobile('plan');}
async function showProjects(){try{const records=await listLocal();openModal(`<h2>Mes projets</h2><p>Projets conservés sur cet appareil. Importez une sauvegarde JSON pour reprendre un projet d’un autre navigateur.</p><button id="import-project-json" class="full">Importer un projet JSON</button><div>${records.length?records.map(p=>`<div class="project-list-item"><div><strong>${esc(p.title)}</strong><small>${p.rooms.length} pièce(s) · ${esc(new Date(p.updatedAt).toLocaleDateString('fr-FR'))}</small></div><button data-load-project="${esc(p.id)}">Ouvrir</button><button class="danger" data-delete-project="${esc(p.id)}" aria-label="Supprimer ${esc(p.title)}">×</button></div>`).join(''):'<p class="note">Aucun projet enregistré pour le moment.</p>'}</div><p id="modal-status" class="modal-status" role="alert"></p><div class="dialog-actions"><button data-close>Fermer</button></div>`,()=>{$('#import-project-json').onclick=()=>{$('#project-file').click();};$$('[data-load-project]').forEach(b=>b.onclick=async()=>{const value=records.find(p=>p.id===b.dataset.loadProject);try{guardLeave(()=>{applyProject(value);modal.close();notify('Projet ouvert.');},'ouvrir');}catch(e){modalStatus(e.message);}});$$('[data-delete-project]').forEach(b=>b.onclick=()=>{const target=records.find(p=>p.id===b.dataset.deleteProject);openModal(`<h2>Supprimer le projet ?</h2><p>La copie locale de « ${esc(target.title)} » sera supprimée. Conservez une sauvegarde JSON si nécessaire.</p><div class="dialog-actions"><button id="keep-project">Conserver</button><button id="backup-before-delete">Télécharger le JSON</button><button id="delete-project-now" class="danger">Supprimer la copie locale</button></div>`,()=>{$('#keep-project').onclick=showProjects;$('#backup-before-delete').onclick=()=>download(target,(target.title||'projet').normalize('NFD').replace(/[^a-zA-Z0-9-]/g,'-')+'.json');$('#delete-project-now').onclick=async()=>{try{await deleteLocal(target.id);if(project.id===target.id){clearTimeout(saveTimer);project=newProject();selected=null;undoStack=[];redoStack=[];cache.clear();renderAll();fit();}await showProjects();}catch(e){notify(e.message);}};});});});}catch(e){openModal(`<h2>Sauvegardes locales indisponibles</h2><p>${esc(e.message)}</p><button id="import-project-json" class="full">Importer un projet JSON</button><div class="dialog-actions"><button data-close>Fermer</button></div>`,()=>{$('#import-project-json').onclick=()=>$('#project-file').click();});}}
async function choosePDFPage(pdf){if(pdf.numPages===1)return {page:1,...await renderPDF(pdf,1)};return new Promise((resolve,reject)=>{let settled=false;const closed=()=>{if(!settled){settled=true;reject(Error('Import du PDF annulé.'));}};openModal(`<h2>Choisir une page du PDF</h2><p>Ce document contient ${pdf.numPages} pages. Importez la page du plan à mesurer.</p><form id="pdf-page-form" class="fields"><label>Page du plan<input id="pdf-page" type="number" min="1" max="${pdf.numPages}" value="1" required></label><p id="modal-status" class="modal-status" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Annuler</button><button class="primary">Importer cette page</button></div></form>`,()=>{modal.addEventListener('close',closed,{once:true});$('#pdf-page-form').onsubmit=async e=>{e.preventDefault();const page=number('#pdf-page');if(!Number.isInteger(page)||page<1||page>pdf.numPages)return modalStatus('Numéro de page invalide.');const button=$('#pdf-page-form button.primary');button.disabled=true;modalStatus('Lecture de la page…');try{const result=await renderPDF(pdf,page);settled=true;modal.close();resolve({...result,page});}catch(error){modalStatus(error.message);button.disabled=false;}};});});}
async function importPlan(file){if(!file||busy)return;let imported=false;busy=true;$('#save-status').textContent='Lecture du plan…';notify('Lecture du plan sur votre appareil…');let pdf;try{let canvas,dimensions=[],page=1,type='image';if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){type='pdf';pdf=await openPDF(file);({canvas,dimensions,page}=await choosePDFPage(pdf));}else canvas=await openImage(file);const source=sourceFromCanvas(canvas,file.name,type,page,dimensions);project=newProject();project.title=file.name.replace(/\.[^.]+$/,'').slice(0,120)||'Mon plan';project.source=source;project.scale=null;selected=null;undoStack=[];redoStack=[];cache.clear();step='plan';showTiles=false;setMode('select');modal.close();changed();fit();mobile('plan');imported=true;notify('Plan importé. Lecture des murs, cloisons et cotes…');}catch(e){$('#save-status').textContent='Import interrompu';notify(e.message);}finally{busy=false;pdf?.destroy();$('#plan-file').value='';}if(imported)await convertPlan();}
async function convertPlan(){
 if(!project.source||busy)return;
 busy=true;
 try{
  await convertSource(project.source,{modal,openModal,onAccept:async({rooms,scale})=>{
   if(project.rooms.length){await saveLocal(project);project=clone(project);project.id=uid();project.title=(project.title+' · conversion').slice(0,120);}
   record();project.scale=scale;project.rooms=rooms.flatMap(r=>splitArchitecture({...newRoom(r.points,r.name),partitions:r.partitions||[]},scale));project.source={...project.source,hidden:true,converted:true};selected=project.rooms[0]?.id||null;sourceOpacity=.65;step='rooms';showTiles=false;setMode('select');changed();fit();mobile('plan');notify('Plan reconstruit : contrôlez les cotes de chaque pièce et les ouvertures proposées.');setTimeout(proposeScanOpenings,100);
  }});
 }catch(e){notify(e.message);}finally{busy=false;}
}
async function detect(){if(!project.source||busy)return;busy=true;notify('Repérage local des pièces fermées…');try{const image=new Image();image.src=project.source.data;await image.decode();const factor=Math.min(1,900/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*factor);canvas.height=Math.round(image.height*factor);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),worker=new Worker(new URL('./recognition.mjs',import.meta.url),{type:'module'});recognitionWorker=worker;const proposals=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{worker.terminate();reject(Error('Le repérage prend trop de temps. Tracez les contours manuellement.'));},20000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data.regions);};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(Error('Repérage indisponible. Utilisez le tracé manuel.'));};worker.postMessage({rgba:pixels.data.buffer,width:canvas.width,height:canvas.height,options:{gap:1}},[pixels.data.buffer]);});const candidates=proposals.map(p=>p.points.map(a=>a.map(v=>v/factor))).filter(p=>!project.rooms.some(r=>p.every(v=>inside(v,r.points))));if(!candidates.length)return notify('Aucune nouvelle pièce fermée repérée. Les portes ouvertes ou les scans difficiles nécessitent un tracé manuel.');openModal(`<h2>${candidates.length} contour(s) proposé(s)</h2><p>Ce repérage détecte des espaces fermés. Il peut confondre une pièce, une légende ou un meuble. Les dimensions et le tracé intérieur restent à contrôler.</p><div class="fields">${candidates.map((p,i)=>`<label class="check"><input type="checkbox" data-proposal="${i}" checked><span>Zone ${i+1} · ${p.length} angles${project.scale?' · environ '+fmt(area(p)*project.scale**2/10000)+' m²':''}</span></label>`).join('')}</div><div class="dialog-actions"><button data-close>Ne pas ajouter</button><button id="accept-proposals" class="primary">Ajouter et vérifier les contours</button></div>`,()=>{$('#accept-proposals').onclick=()=>{const checked=$$('[data-proposal]:checked').map(e=>candidates[Number(e.dataset.proposal)]);if(checked.length+project.rooms.length>60)return notify('60 pièces maximum par projet.');record();for(const p of checked){const r=newRoom(p,'Pièce '+(project.rooms.length+1));project.rooms.push(r);selected=r.id;}modal.close();step='rooms';changed();fit();mobile('plan');notify('Contours proposés ajoutés. Ajustez-les sur les faces intérieures des murs, puis validez chaque pièce.');};});}catch(e){notify(e.message);}finally{recognitionWorker=null;busy=false;}}
const filename=()=>((project.title||'lrf-plan-pose').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').slice(0,70)||'lrf-plan-pose');
function exportNative(target,requestedFloor){const selectedFloor=requestedFloor??$('#transfer-floor')?.checked;if(hasChanges())return showSave(()=>exportNative(target,selectedFloor));try{
 const chosen=project.rooms.filter(r=>transferRooms.has(r.id));if(!chosen.length)throw Error('Sélectionnez au moins une pièce à transférer.');const floor=selectedFloor;
 const transfers=chosen.map(original=>{const r=clone(original);if(!['straight','offset'].includes(r.layout.pattern))throw Error('La pose « '+r.layout.pattern+' » de '+r.name+' est conservée dans PLAN & POSE. Le moteur RANDAL actuel accepte la pose droite ou décalée ½ : choisissez une pose compatible avant le transfert.');
 if(floor){const match=catalogue?.products.find(p=>p.key===r.tile.key);if(!match||!r.tile.native||match.available3d===false)throw Error(r.name+' : carrelage sans correspondance 3D vérifiée. Décochez le transfert du carrelage pour transmettre le plan.');r.tile.color=r.tile.colorId||r.tile.color;}else r.tile={...newTile(),brand:'ELIOS',collection:'Shell',color:'beige',width:120,height:60,format:'60x120',allowOffset:true};
 const data=nativeProject(project,r,target),url=new URL(target==='studio'?'https://leroyfactory.fr/studio-one-configurateur.html':'https://leroyfactory.fr/randal-configurateur.html');url.searchParams.set('page','atelier.html');url.hash='projet='+encodeNative(data);return {r:original,url:url.href};});
 const label=target==='studio'?'RANDAL STUDIO ONE':'RANDAL Général';openModal(`<h2>Transférer vers ${label}</h2><p>${transfers.length} pièce(s) préparée(s). Chaque bouton ouvre une composition indépendante avec la fiche client du projet.</p><div class="fields">${transfers.map((t,i)=>`<a class="primary download-link" data-open-transfer="${i}" target="_blank" rel="noopener" href="${esc(t.url)}">Ouvrir ${esc(t.r.name)} dans ${label}</a>`).join('')}<button data-close>Revenir au projet</button></div>`,()=>{$$('[data-open-transfer]').forEach(a=>a.onclick=()=>{const r=transfers[Number(a.dataset.openTransfer)].r;project.transfers=[...(project.transfers||[]).filter(t=>!(t.roomId===r.id&&t.target===target)),{roomId:r.id,roomName:r.name,target,at:new Date().toISOString()}];listLocal().then(rows=>{const saved=rows.find(p=>p.id===project.id);if(saved)return saveLocal({...saved,transfers:clone(project.transfers)});}).catch(()=>notify('Historique du transfert non sauvegardé.'));renderSide();notify(r.name+' · transfert ouvert vers '+label+'.');});});
 }catch(e){notify(e.message);}}
async function planPNG(){
 if(planExportPending)throw Error('Un export du plan est déjà en cours.');planExportPending=true;
 try{
  const signature=planSignature(),before={...view};let fitView;
  try{exporting=true;fit();fitView={...view};}finally{exporting=false;view=before;renderBoard();}
  const ratio=fitView.h/fitView.w,pixelWidth=4096/Math.max(1,ratio),products=project.rooms.map(r=>{const p=textureProduct(r.tile,catalogue);if(!p)return null;const layout=calculation(r).layout,count=textureSources(p,'max').length;return {...p,textureExportSize:Math.min(4096,Math.max(p.width,p.height)/project.scale*pixelWidth/fitView.w),textureFaces:[...new Set(layout.cells.map(cell=>textureFace(cell,count)))]};}).filter(Boolean);
  const exportTextures=new TextureCache(()=>{},{strictResolution:true,fetcher:textureFetch});let hd;
  try{hd=await exportTextures.prepareHD(products);}finally{exportTextures.dispose();}
  if(signature!==planSignature())throw Error('Le plan a changé pendant la préparation. Relancez son export.');
  const previous={view:{...view},showTiles,exporting,exportTextureData};let element,width,height;
  try{
   exporting=true;showTiles=true;exportTextureData=hd;fit();element=board.cloneNode(true);element.querySelectorAll('.vertex').forEach(e=>e.remove());
   const ratio=view.h/view.w;if(ratio>=1){height=4096;width=Math.max(1,Math.round(height/ratio));}else{width=4096;height=Math.max(1,Math.round(width*ratio));}
   element.setAttribute('width',width);element.setAttribute('height',height);
   const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.plinth-edge{stroke:#ad8b48;stroke-width:2;fill:none}.plinth-joint{stroke:#fffefa;stroke-width:.6;fill:none}.partition{fill:#383a33;stroke:#272a24;stroke-width:.7}.room-shape{stroke:#a1977e;stroke-width:1.5;fill:#dedbc9;fill-opacity:.35}.room.selected .room-shape{stroke:#a78443;stroke-width:2}.room-label{fill:#434d3e;font-family:Arial,sans-serif;text-anchor:middle;paint-order:stroke;stroke:#faf8ef;stroke-width:2}.dimension{fill:#727666;font-family:Arial,sans-serif;text-anchor:middle;paint-order:stroke;stroke:#f7f5ed;stroke-width:2}.tile{stroke:#988f7b;stroke-width:.45;fill:#ede4cc;fill-opacity:.55}.tile.cut{fill:#e4d4b3}.opening{stroke:#faf8f1;stroke-width:8}.opening-mark{stroke:#58776a;stroke-width:2}';element.prepend(style);
  }finally{exporting=previous.exporting;showTiles=previous.showTiles;exportTextureData=previous.exportTextureData;view=previous.view;renderBoard();}
  const data=new XMLSerializer().serializeToString(element),url=URL.createObjectURL(new Blob([data],{type:'image/svg+xml;charset=utf-8'}));
  try{
   const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
   const context=canvas.getContext('2d');if(!context)throw Error('Mémoire insuffisante pour créer le plan HD.');context.fillStyle='#faf8f1';context.fillRect(0,0,width,height);context.drawImage(image,0,0,width,height);
   const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('L’image HD n’a pas pu être créée.');
   if(signature!==planSignature())throw Error('Le plan a changé pendant l’export. Relancez son export.');
   return {data:canvas.toDataURL('image/png'),jpeg:canvas.toDataURL('image/jpeg',.92),width,height,blob};
  }finally{URL.revokeObjectURL(url);}
 }finally{planExportPending=false;}
}
async function exportPNG(){if(!project.rooms.length&&!project.source)return notify('Ajoutez d’abord un plan.');try{const image=await planPNG();download(image.blob,filename()+'-plan-hd.png','image/png');}catch(e){notify('L’image n’a pas pu être créée : '+e.message);}}
let pdfExportPromise;async function loadPDFExport(){if(globalThis.jspdf?.jsPDF)return globalThis.jspdf.jsPDF;if(!pdfExportPromise)pdfExportPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL('../../vendor/randal-catalogue/jspdf.umd.min.js',import.meta.url);script.onload=()=>globalThis.jspdf?.jsPDF?resolve(globalThis.jspdf.jsPDF):reject(Error('Export PDF indisponible.'));script.onerror=()=>{pdfExportPromise=null;reject(Error('La bibliothèque PDF n’a pas pu être chargée.'));};document.head.append(script);});return pdfExportPromise;}
async function exportPDF(share=false){share=share===true;if(!project.rooms.length)return notify('Ajoutez d’abord une pièce.');try{notify('Préparation du dossier PDF…');const jsPDF=await loadPDFExport();notify('Création du plan pour le PDF…');const image=await recapPlanImage();notify('Assemblage du dossier PDF…');const rows=project.rooms.filter(r=>r.included).map(r=>({r,...calculation(r).q}));const output=buildPDFReport(jsPDF,project,rows,image,{includePurchase:proVerified&&includePurchasePDF}),name=filename()+'-dossier.pdf',fileURL=URL.createObjectURL(output);if(share){const file=new File([output],name,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:project.title});URL.revokeObjectURL(fileURL);return;}}openModal('<h2>Votre dossier PDF est prêt.</h2><p>Le plan, les métrés et le chiffrage renseigné sont réunis dans ce dossier.</p><div class="dialog-actions"><button data-close>Fermer</button><a id="download-ready-pdf" class="primary download-link" href="'+fileURL+'" download="'+esc(name)+'">Télécharger le dossier PDF</a></div>',()=>{modal.addEventListener('close',()=>setTimeout(()=>URL.revokeObjectURL(fileURL),30000),{once:true});});}catch(e){notify(e.message||'Le dossier PDF n’a pas pu être créé.');}}
function miniature(r){const b=bounds(r.points),pad=Math.max(b.width,b.height)*.08,layout=calculation(r).layout;return `<svg class="recap-plan" viewBox="${b.minX-pad} ${b.minY-pad} ${b.width+pad*2} ${b.height+pad*2}" role="img" aria-label="Calepinage de ${esc(r.name)}"><path d="M${r.points.map(p=>p.join(',')).join('L')}Z" fill="#f2ebd9" stroke="#827965" stroke-width="2"/>${layout.error?'':layout.cells.slice(0,2500).map(c=>`<polygon points="${c.polygon.map(layout.transform.from).map(p=>p.join(',')).join(' ')}" fill="${c.cut?'#dcca9e':'#f8f5ed'}" stroke="#b6ac92" stroke-width=".6"/>`).join('')}</svg>`;}
let recapImagePromise=null,recapImageKey='';
function planSignature(){return JSON.stringify([project.scale,project.source,project.rooms.map(r=>[r.id,r.name,r.points,r.partitions,r.holes,r.openings,r.tile,r.layout,r.plinths,r.plinthExclusions,r.confirmed])]);}
function recapPlanImage(){const key=planSignature();if(key!==recapImageKey||!recapImagePromise){recapImageKey=key;recapImagePromise=planPNG().catch(e=>{recapImagePromise=null;throw e;});}return recapImagePromise;}
function showDetailedSummary(){
 const rows=projectRows(),lines=orderLines(rows),plinthLines=plinthOrderLines(rows),quote=publicQuote(rows,project);openModal(`<p class="eyebrow">BILAN DU PROJET</p><h2>Mon récapitulatif</h2><p>${esc(project.title)}${project.client?.name?' · '+esc(project.client.name):''}</p><div id="recap-project-plan"><p class="subtle">Préparation du plan chiffré…</p></div><div class="recap-rooms">${rows.map(x=>{const sale=project.sales?.[x.r.id]||{},q=quote.lines.find(q=>q.roomId===x.r.id);return `<article class="recap-room"><div><h3>${esc(x.r.name)}</h3><small>${x.r.confirmed?'Cotes validées':'Cotes à vérifier'}</small></div><div>${x.error?`<p class="note error">${esc(x.error)}</p>`:`<div class="product-chosen">${safeURL(x.r.tile.preview)?`<img src="${esc(safeURL(x.r.tile.preview))}" alt="${esc(x.r.tile.collection)}">`:''}<div><strong>${esc(x.r.tile.brand+' · '+x.r.tile.collection+' '+x.r.tile.color)}</strong><small>Réf. ${esc(x.r.tile.reference||'à confirmer')} · ${esc(x.r.tile.format)} cm</small></div></div><dl class="recap-values"><div><dt>Sol net / commande</dt><dd>${fmt(x.area)} / ${fmt(x.orderArea)} m²</dd></div><div><dt>Boîtage</dt><dd>${x.r.tile.packVerified?x.r.tile.packPieces+' pièces · '+fmt(x.r.tile.packArea)+' m²':'À confirmer'}</dd></div><div><dt>Cartons / carreaux</dt><dd>${x.boxes??'—'} / ${x.orderPieces??'—'}</dd></div><div><dt>Pertes et chutes du sol</dt><dd>${fmt(x.cutWaste)} m² · marge ${project.loss} %</dd></div><div><dt>Plinthes nettes / à commander</dt><dd>${fmt(x.plinths.net)} / ${fmt(x.plinths.order)} ml</dd></div></dl><p>${x.plinths.type==='factory'?'Plinthes fabricant · '+esc(x.plinths.product?.reference||'')+' · '+x.plinths.boxes+' boîte(s)':x.plinths.type==='wood'?x.plinths.units+' barres bois blanc · 2,20 m':x.plinths.tiles+' carreaux réservés aux plinthes'}</p><div class="cols"><label>Votre prix de vente / m²<input type="number" min="0" max="100000" step=".01" data-sale-room="${x.r.id}" data-sale-field="floor" value="${sale.floor??x.r.tile.priceTTC??''}" placeholder="Prix sur demande"></label><label>Votre prix de vente plinthes / ml<input type="number" min="0" max="100000" step=".01" data-sale-room="${x.r.id}" data-sale-field="plinth" value="${sale.plinth??''}" placeholder="Prix sur demande"></label></div><p class="quote-total">${q?.total!==null?'Montant de cette pièce : '+money(q?.total):'Prix à compléter'}</p>`}</div></article>`;}).join('')}</div><h3>Commandes regroupées par référence</h3>${lines.map(l=>`<p>${esc(l.tile.reference||l.tile.collection)} · ${l.boxes??'—'} boîte(s) · ${fmt(l.orderArea)} m²</p>`).join('')}${plinthLines.map(l=>`<p>Plinthes ${esc(l.product?.reference||'bois blanc')} · ${l.boxes??l.units} ${l.type==='factory'?'boîte(s)':'barre(s)'}</p>`).join('')}<div class="metric-line"><span>Total de vente du projet</span><strong>${money(quote.total)}</strong></div><label>Commentaire du projet<textarea id="project-comment" rows="4" maxlength="4000" placeholder="Informations utiles, consignes de pose…">${esc(project.comment)}</textarea></label>${proVerified?`<button type="button" data-toggle-prices>${purchaseVisible?'Masquer les prix d’achat HT':'Voir les prix d’achat HT'}</button>${purchaseVisible?purchaseTotalsMarkup(rows):''}`:''}<div class="fields"><button id="download-from-summary" class="primary">Créer le dossier PDF A4</button><button id="share-quote">Envoyer le dossier PDF</button><button id="save-from-summary">Enregistrer le projet</button><button data-close>Revenir au plan</button></div>`,()=>{modal.dataset.summary='true';$('#download-from-summary').onclick=exportPDF;$('#share-quote').onclick=()=>exportPDF(true);$('#save-from-summary').onclick=()=>showSave();$('#project-comment').onchange=e=>{record();project.comment=e.target.value.slice(0,4000);changed({render:false});};$$('[data-sale-room]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return;record();const id=el.dataset.saleRoom;project.sales={...(project.sales||{}),[id]:{...(project.sales?.[id]||{}),[el.dataset.saleField]:el.value===''?null:Number(el.value)}};changed({render:false});showDetailedSummary();});bindPriceButtons(modal);});
 recapPlanImage().then(img=>{const slot=$('#recap-project-plan');if(slot){slot.innerHTML=`<img class="recap-complete-plan" alt="Plan du projet avec cotes et calepinage" src="${img.jpeg}">`;}}).catch(e=>{const slot=$('#recap-project-plan');if(slot)slot.innerHTML=`<p class="note">${esc(e.message)} Le plan reste visible dans l’éditeur.</p>`;});
}

$$('[data-step]').forEach(b=>b.onclick=()=>chooseStep(b.dataset.step));$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('[data-mobile]').forEach(b=>b.onclick=()=>{mobile(b.dataset.mobile);if(b.dataset.mobile==='plan')requestAnimationFrame(renderBoard);});$('#convert-source').onclick=convertPlan;$('#finish-draw').onclick=finishDraw;$('#cancel-mode').onclick=()=>setMode('select');$('#fit').onclick=fit;$('#zoom-in').onclick=()=>zoom(1/1.2);$('#zoom-out').onclick=()=>zoom(1.2);$('#new-project').onclick=startNew;$('#open-projects').onclick=showProjects;$('#save-project').onclick=()=>showSave();$('#exit-project').onclick=exitApplication;$('.brand').onclick=e=>{e.preventDefault();exitApplication();};$('#empty-import').onclick=()=>$('#plan-file').click();$('#empty-room').onclick=showManualRoom;
$('#project-title').onchange=e=>{record();project.title=e.target.value.trim().slice(0,120)||'Mon projet';changed();};$('#project-reference').onchange=e=>{record();project.reference=e.target.value.trim().slice(0,100);changed();};
function history(direction){const from=direction==='undo'?undoStack:redoStack,to=direction==='undo'?redoStack:undoStack;if(!from.length)return;to.push(snapshot());project=from.pop();cache.clear();if(!project.rooms.some(r=>r.id===selected))selected=project.rooms[0]?.id||null;mode='select';draft=[];changed();}
$('#undo').onclick=()=>history('undo');$('#redo').onclick=()=>history('redo');addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal.open)modal.close();setMode('select');return;}if(e.target.matches('input,textarea,select')||modal.open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();history(e.shiftKey?'redo':'undo');}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist();}if(e.key==='Enter'&&['draw','hole'].includes(mode)){e.preventDefault();finishDraw();}});
$('#plan-file').onchange=e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;guardLeave(()=>importPlan(file),'importer');};$('#camera-file').onchange=e=>{const f=e.target.files?.[0];e.target.value='';if(f)guardLeave(()=>importPlan(f),'importer');};$('#project-file').onchange=async e=>{try{const file=e.target.files?.[0];if(!file)return;const value=await readProject(file);guardLeave(()=>{applyProject(value);modal.close();persist(false);notify('Projet importé.');},'ouvrir');}catch(error){notify(error.message);}finally{e.target.value='';}};
new ResizeObserver(()=>requestAnimationFrame(renderBoard)).observe($('.drawing'));
renderAll();fit();
