async function proposeScanOpenings(){try{const image=new Image();image.src=project.source.data;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;const proposals=project.rooms.flatMap(r=>scanOpenings(data,canvas.width,canvas.height,r,project.scale).map(o=>({r,o})));if(!proposals.length)return;
 openModal(`<h2>Ouvertures repérées · à vérifier</h2><p>Les interruptions de murs ci-dessous peuvent correspondre à des portes ou fenêtres. Vérifiez le type et les dimensions. Aucun symbole n’est considéré comme une mesure garantie.</p>${proposals.map((p,i)=>`<label class="check"><input type="checkbox" data-scan-opening="${i}"><span>${esc(p.r.name)} · mur ${p.o.wall+1} · ${p.o.width} cm</span></label>`).join('')}<div class="dialog-actions"><button data-close>Ignorer</button><button id="scan-openings-accept" class="primary">Ajouter les ouvertures choisies</button></div>`,()=>{$('#scan-openings-accept').onclick=()=>{const selected=$$('[data-scan-opening]:checked').map(e=>proposals[Number(e.dataset.scanOpening)]);record();for(const {r,o}of selected){if(!roomError({...r,openings:[...r.openings,o]},project.scale))r.openings.push(o);}modal.close();changed({all:true});notify('Ouvertures ajoutées. Sélectionnez-les pour vérifier leur type, leurs dimensions et leur hauteur.');};});
 }catch{notify('Repérage des ouvertures indisponible. Ajoutez-les avec la palette latérale.');}}
